CREATE TABLE usuarios (id CHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(60) NOT NULL, rol ENUM('COLABORADOR','RRHH') NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE, creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE departamentos (id CHAR(36) PRIMARY KEY, nombre VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE puestos (id CHAR(36) PRIMARY KEY, departamento_id CHAR(36) NOT NULL, nombre VARCHAR(120) NOT NULL, UNIQUE KEY uq_puesto (departamento_id,nombre), UNIQUE KEY uq_puesto_departamento (id,departamento_id), FOREIGN KEY (departamento_id) REFERENCES departamentos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE colaboradores (id CHAR(36) PRIMARY KEY, usuario_id CHAR(36) NOT NULL UNIQUE, departamento_id CHAR(36) NOT NULL, puesto_id CHAR(36) NOT NULL, codigo VARCHAR(16) NOT NULL UNIQUE, identificacion_ficticia VARCHAR(32) NOT NULL UNIQUE, nombres VARCHAR(100) NOT NULL, apellidos VARCHAR(100) NOT NULL, email_corporativo VARCHAR(254) NOT NULL UNIQUE, fecha_ingreso DATE NOT NULL, fecha_salida DATE, modalidad ENUM('PRESENCIAL','HIBRIDO','TELETRABAJO') NOT NULL, salario_base DECIMAL(14,2) NOT NULL, estado ENUM('ACTIVO','INACTIVO','SUSPENDIDO') NOT NULL, FOREIGN KEY (usuario_id) REFERENCES usuarios(id), FOREIGN KEY (departamento_id) REFERENCES departamentos(id), FOREIGN KEY (puesto_id,departamento_id) REFERENCES puestos(id,departamento_id), CONSTRAINT ck_colaborador_salario CHECK (salario_base >= 0), CONSTRAINT ck_colaborador_fechas CHECK (fecha_salida IS NULL OR fecha_salida >= fecha_ingreso), INDEX idx_colaboradores_estado_departamento (estado,departamento_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE saldos_vacaciones (id CHAR(36) PRIMARY KEY, colaborador_id CHAR(36) NOT NULL, periodo_anual SMALLINT NOT NULL, dias_generados DECIMAL(5,2) NOT NULL, dias_disfrutados DECIMAL(5,2) NOT NULL DEFAULT 0, dias_ajuste DECIMAL(5,2) NOT NULL DEFAULT 0, dias_disponibles DECIMAL(5,2) GENERATED ALWAYS AS (dias_generados + dias_ajuste - dias_disfrutados) STORED, UNIQUE KEY uq_saldo (colaborador_id,periodo_anual), FOREIGN KEY (colaborador_id) REFERENCES colaboradores(id), CONSTRAINT ck_saldo CHECK (dias_generados >= 0 AND dias_disfrutados >= 0 AND dias_generados + dias_ajuste >= dias_disfrutados)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE solicitudes (id CHAR(36) PRIMARY KEY, colaborador_id CHAR(36) NOT NULL, tipo ENUM('VACACIONES','PERMISO_PERSONAL','PERMISO_DUELO','PERMISO_FORMACION','LICENCIA_SIN_GOCE','OTRA') NOT NULL, fecha_inicio DATE NOT NULL, fecha_fin DATE NOT NULL, dias_solicitados DECIMAL(5,2) NOT NULL, estado ENUM('PENDIENTE','APROBADA','RECHAZADA','CANCELADA') NOT NULL DEFAULT 'PENDIENTE', creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (colaborador_id) REFERENCES colaboradores(id), CHECK (fecha_fin >= fecha_inicio AND dias_solicitados > 0), INDEX idx_solicitudes_colaborador_estado (colaborador_id,estado)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE incapacidades (id CHAR(36) PRIMARY KEY, colaborador_id CHAR(36) NOT NULL, referencia_ccss VARCHAR(80) NOT NULL UNIQUE, fecha_inicio DATE NOT NULL, fecha_fin DATE NOT NULL, estado ENUM('REGISTRADA','EN_REVISION','CERRADA') NOT NULL, FOREIGN KEY (colaborador_id) REFERENCES colaboradores(id), CHECK (fecha_fin >= fecha_inicio), INDEX idx_incapacidad_fechas (fecha_inicio,fecha_fin)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE movimientos_personal (id CHAR(36) PRIMARY KEY, colaborador_id CHAR(36) NOT NULL, tipo ENUM('INGRESO','SALIDA','ASCENSO','CAMBIO_PUESTO','CAMBIO_DEPARTAMENTO') NOT NULL, fecha_efectiva DATE NOT NULL, detalle JSON NOT NULL, FOREIGN KEY (colaborador_id) REFERENCES colaboradores(id), INDEX idx_movimiento_fecha_tipo (fecha_efectiva,tipo)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE calendario_pagos (id CHAR(36) PRIMARY KEY, fecha_pago DATE NOT NULL UNIQUE, fecha_corte_inicio DATE NOT NULL, fecha_corte_fin DATE NOT NULL, tipo ENUM('QUINCENA_1','QUINCENA_2','AGUINALDO','EXTRAORDINARIO') NOT NULL, estado ENUM('PROGRAMADO','PROCESADO','CANCELADO') NOT NULL, CHECK (fecha_corte_fin >= fecha_corte_inicio)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE evaluaciones_desempeno (id CHAR(36) PRIMARY KEY, colaborador_id CHAR(36) NOT NULL, evaluador_id CHAR(36), periodo_inicio DATE NOT NULL, periodo_fin DATE NOT NULL, estado ENUM('BORRADOR','PENDIENTE','COMPLETADA') NOT NULL, resultado VARCHAR(80), resumen TEXT, FOREIGN KEY (colaborador_id) REFERENCES colaboradores(id), FOREIGN KEY (evaluador_id) REFERENCES colaboradores(id), UNIQUE KEY uq_evaluacion (colaborador_id,periodo_inicio,periodo_fin), CHECK (periodo_fin >= periodo_inicio)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE consultas_chat (id CHAR(36) PRIMARY KEY, usuario_id CHAR(36) NOT NULL, pregunta TEXT NOT NULL, respuesta TEXT, agente VARCHAR(80), creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, resolucion ENUM('RESPONDIDA','SIN_EVIDENCIA','ERROR'), latencia_ms INT UNSIGNED, fragmentos_utilizados JSON, documentos_citados JSON, FOREIGN KEY (usuario_id) REFERENCES usuarios(id), INDEX idx_chat_usuario_fecha (usuario_id,creado_en)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE reportes_diarios (id CHAR(36) PRIMARY KEY, fecha DATE NOT NULL UNIQUE, metricas JSON NOT NULL, creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE documentos (id CHAR(36) PRIMARY KEY, drive_file_id VARCHAR(255) NOT NULL UNIQUE, titulo VARCHAR(250) NOT NULL, version VARCHAR(32) NOT NULL, estado ENUM('PENDIENTE','VALIDADO','ELIMINADO') NOT NULL, content_hash CHAR(64), actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE sincronizaciones (id CHAR(36) PRIMARY KEY, origen VARCHAR(80) NOT NULL, estado ENUM('PENDIENTE','EN_PROCESO','COMPLETADA','FALLIDA') NOT NULL, inicio_en DATETIME, finalizo_en DATETIME, documentos_leidos INT NOT NULL DEFAULT 0, documentos_actualizados INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE logs_agentes (id CHAR(36) PRIMARY KEY, consulta_chat_id CHAR(36), agente VARCHAR(80) NOT NULL, operacion VARCHAR(120) NOT NULL, estado ENUM('INICIADO','COMPLETADO','ERROR') NOT NULL, creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (consulta_chat_id) REFERENCES consultas_chat(id), INDEX idx_logs_agentes_fecha (agente,creado_en)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
